package network.vonix.viscord;
import network.vonix.viscord.config.toml.*; import network.vonix.viscord.discord.*; import network.vonix.viscord.platform.PlatformEvents; import org.apache.logging.log4j.*; import java.nio.file.*; import java.util.concurrent.*; import java.util.concurrent.atomic.AtomicLong;
public final class Viscord { public static final String MOD_ID="viscord"; public static final Logger LOGGER=LogManager.getLogger(MOD_ID); private static Viscord instance; private volatile boolean discordEnabled; public static final ScheduledThreadPoolExecutor ASYNC_EXECUTOR=buildExecutor(); private static ScheduledThreadPoolExecutor buildExecutor(){int c=Math.max(2,Runtime.getRuntime().availableProcessors()/2);AtomicLong n=new AtomicLong();ScheduledThreadPoolExecutor e=new ScheduledThreadPoolExecutor(c,r->{Thread t=new Thread(r,"Viscord-Async-"+n.incrementAndGet());t.setDaemon(true);return t;});e.setMaximumPoolSize(Math.max(8,c*2));e.setKeepAliveTime(30,TimeUnit.SECONDS);e.allowCoreThreadTimeOut(true);e.setRemoveOnCancelPolicy(true);e.setRejectedExecutionHandler(new ThreadPoolExecutor.CallerRunsPolicy());return e;} public static void executeAsync(Runnable r){ASYNC_EXECUTOR.submit(r);} public static void scheduleAsync(Runnable r,long ms){ASYNC_EXECUTOR.schedule(r,ms,TimeUnit.MILLISECONDS);} public static void init(){instance=new Viscord();instance.onInitialize();} public static Viscord getInstance(){return instance;} private void onInitialize(){Path d=PlatformEvents.Holder.get().configDirectory().resolve("viscord");try{Files.createDirectories(d);}catch(Exception e){LOGGER.error("[Viscord] config directory failed",e);}TomlConfigManager.load(d);PlatformEvents.Holder.get().register(new PlatformEvents.Callbacks(DiscordEventHandler::registerCommands,this::onServerStarted,this::onServerStopping,DiscordEventHandler::onPlayerJoin,DiscordEventHandler::onPlayerQuit,DiscordEventHandler::onLivingDeath));} private void onServerStarted(net.minecraft.server.MinecraftServer s){if(!ViscordConfigToml.General.ENABLED.get())return;CompletableFuture.runAsync(()->{try{DiscordManager.getInstance().initialize(s);discordEnabled=true;}catch(Exception e){LOGGER.error("[Viscord] initialization failed",e);}},ASYNC_EXECUTOR);} private void onServerStopping(net.minecraft.server.MinecraftServer s){if(!discordEnabled){ASYNC_EXECUTOR.shutdown();return;}CompletableFuture.runAsync(()->{try{DiscordManager.getInstance().shutdown();}finally{ASYNC_EXECUTOR.shutdown();}},ASYNC_EXECUTOR).orTimeout(5,TimeUnit.SECONDS);}}
